('f8a687f1-3208-11f1-b570-0a0027000013', '01995e0c-9825-73b3-b94f-2ae0542eabef', 'Program Cek Lulus', '<p>Tentukan apakah siswa lulus jika nilai lebih dari atau sama dengan 75.</p>', '[{\"variabel\": \"nilai\", \"tipe_data\": \"int\"}]', '[{\"langkah\": \"START\"}, {\"langkah\": \"IF\"}, {\"langkah\": \"OUTPUT\"}, {\"langkah\": \"END\"}]', 10, 1, '2026-04-06 22:35:53', '2026-04-06 22:35:53', NULL, 'easy'),
